// Embedded brand typefaces (base64 TTFs) so the certificate PDF can be
// generated identically in dev and in the bundled production build.
// Space Grotesk 2.0.0 + JetBrains Mono 2.304 static weights.

const SPACE_GROTESK_REGULAR =
  "";

const SPACE_GROTESK_MEDIUM =
  "";

const SPACE_GROTESK_BOLD =
  "";

const JETBRAINS_MONO_REGULAR =
  "";

const JETBRAINS_MONO_BOLD =
  "";

/** Register every brand face on a pdfkit document under a stable alias. */
export const registerCertificateFonts = (doc: PDFKit.PDFDocument): void => {
  doc.registerFont("SpaceGrotesk", Buffer.from(SPACE_GROTESK_REGULAR, "base64"));
  doc.registerFont("SpaceGrotesk-Medium", Buffer.from(SPACE_GROTESK_MEDIUM, "base64"));
  doc.registerFont("SpaceGrotesk-Bold", Buffer.from(SPACE_GROTESK_BOLD, "base64"));
  doc.registerFont("JetBrainsMono", Buffer.from(JETBRAINS_MONO_REGULAR, "base64"));
  doc.registerFont("JetBrainsMono-Bold", Buffer.from(JETBRAINS_MONO_BOLD, "base64"));
};
